if(document.body.dataset.page==='brands'){const rows=[...document.querySelectorAll('.brand-row')],whiteSheep=rows[3];if(whiteSheep&&!document.querySelector('.bell-row')){const bell=document.createElement('section');bell.className='brand-row bell-row';bell.style.setProperty('--brand-tone','#d9d7cb');bell.innerHTML='<div class="brand-row-copy"><h2 class="official-logo"><img src="data:image/png;base64," alt="Bell Standart"></h2><strong>Традиції італійського догляду</strong><p>Засоби для прання, дому та щоденного догляду, у яких практичність поєднується з м’якістю і знайомими ритуалами чистоти.</p><div class="brand-categories"><span>Home Care</span><span>Laundry Care</span><span>Hand Care</span></div></div><div class="bell-intro"><span>Bell Standart</span><p>Асортимент бренду представимо тут окремою каруселлю з оригінальними фото продуктів.</p></div>';whiteSheep.before(bell)}document.head.insertAdjacentHTML('beforeend','<style>.bell-row{background:#f7f6f0}.bell-row h2.official-logo{width:330px;height:170px;margin:0 0 18px}.bell-row h2.official-logo img{display:block;width:100%;height:100%;object-fit:contain}.bell-intro{display:flex;min-height:250px;align-items:center;justify-content:center;flex-direction:column;background:linear-gradient(135deg,#eff0e9,#f8f4ee);padding:35px;color:#39382f;text-align:center}.bell-intro span{font:12px/1.2 DM Mono,monospace;letter-spacing:.12em;text-transform:uppercase}.bell-intro p{max-width:340px;margin:18px 0 0;font-size:17px;line-height:1.55}@media(max-width:800px){.bell-row h2.official-logo{width:280px;height:140px}.bell-intro{min-height:160px}}</style>')}
if(document.body.dataset.page==='certification'){const section=document.createElement('section');section.className='certification-scope reveal show';section.innerHTML='<div class="section-title">Повний цикл супроводу</div><div class="certification-scope-head"><h2>Від перевірки<br>до <em>нотифікації.</em></h2><p>UNIKS супроводжує косметичну продукцію, яку ми виробляємо, а також продукти інших брендів, виготовлені на сторонніх виробництвах. Працюємо з виробниками, імпортерами та власниками торгових марок.</p></div><div class="certification-note"><strong>Нові вимоги ринку</strong><p>З 3 серпня 2026 року косметична продукція має відповідати вимогам Технічного регламенту та порядку нотифікації, щоб законно перебувати в обігу в Україні.</p></div><div class="certification-grid"><article><span>01</span><h3>Аудит продукту</h3><p>Перевіряємо формулу, склад, маркування та наявні документи. Визначаємо, яких даних бракує для коректного маршруту.</p></article><article><span>02</span><h3>Продуктове досьє</h3><p>Готуємо PIF-файл, CPSR / звіт про безпечність, матеріали щодо сировини, випробувань і заявлених властивостей продукту.</p></article><article><span>03</span><h3>Відповідальна особа</h3><p>За потреби UNIKS виконує функції Responsible Person або супроводжує взаємодію з відповідальною особою замовника.</p></article><article><span>04</span><h3>Нотифікація</h3><p>Супроводжуємо внесення даних до електронної системи та підготовку документів для запитів органів ринкового нагляду.</p></article></div><p class="certification-footnote">Повний пакет формується відповідно до конкретного продукту: склад, категорія, виробництво, маркування та необхідні випробування можуть відрізнятися.</p>';document.querySelector('.intro')?.after(section);document.head.insertAdjacentHTML('beforeend','<style>.certification-scope{background:#f7f2fa}.certification-scope-head{display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:end;margin-bottom:42px}.certification-scope h2{margin:0;font-size:clamp(40px,4.5vw,68px);line-height:.94}.certification-scope h2 em{color:#7a4d91}.certification-scope-head p{margin:0;max-width:530px;color:#5f5265;font-size:17px;line-height:1.65}.certification-note{display:grid;grid-template-columns:210px 1fr;gap:28px;padding:25px 28px;background:#e8dff0;border-left:3px solid #7a4d91;margin-bottom:16px}.certification-note strong{font:13px/1.25 DM Mono,monospace;letter-spacing:.08em;text-transform:uppercase}.certification-note p{margin:0;line-height:1.6}.certification-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.certification-grid article{min-height:240px;padding:24px;background:#fff}.certification-grid span{font:12px/1 DM Mono,monospace;color:#7a4d91}.certification-grid h3{margin:46px 0 12px;font-size:26px;line-height:.95}.certification-grid p,.certification-footnote{font-size:14px;line-height:1.6;color:#5f5265}.certification-footnote{max-width:780px;margin:28px 0 0}@media(max-width:850px){.certification-scope-head{grid-template-columns:1fr;gap:18px}.certification-grid{grid-template-columns:repeat(2,1fr)}.certification-note{grid-template-columns:1fr}}@media(max-width:520px){.certification-grid{grid-template-columns:1fr}.certification-grid article{min-height:190px}}</style>')}
